<script setup lang="ts">
import {computed,ref,shallowRef,onMounted,nextTick,onBeforeUnmount} from 'vue'
import {VueFlow,Handle,Position,useVueFlow,type Node,type Edge,type Connection} from '@vue-flow/core'
import UModal from '@nuxt/ui/components/Modal.vue'
import {analysisLines} from '../cost/cost-review'
import type {Source,Row} from '../frame/types'
import {confirmReason} from '../frame/ai-protocol'
import {bjTime} from './time'
interface Cell{id:string;kind:string;name:string;productCode:string;unit:string;inputUnit:string;outputUnit:string;reportingRequired:boolean;position:{x:number;y:number}}
interface Item{id:string;materialCode:string;nodeId:string;quantity:number;base:number;unit:string;baseUnit:string;sourceId?:string}
interface Definition{nodes:Cell[];edges:{id:string;source:string;target:string}[];bom:Item[]}
interface Revision{definition:Definition;hash:string;sourceRevision:string;at:string;version:number;productionVersion?:number}
interface Stored{version:number;draft:Revision|null;published:Revision[];activeProductionVersion?:number}
const props=defineProps<{source:Source;project:Row}>(),emit=defineEmits<{close:[]}>()
const code=String(props.project.productCode),rs=(k:string)=>props.source.resources[k]||[]
const def=ref<Definition>({nodes:[],edges:[],bom:[]}),saved=ref<Stored>({version:0,draft:null,published:[]}),selected=ref(''),tab=ref('configure'),dirty=ref(false),busy=ref(false),error=ref(''),notice=ref(''),preview=ref(false),aiOpen=ref(false),aiText=ref(''),aiQuestion=ref('检查当前本地草稿和真实工单的区别，保留零值和缺失，不将草稿当作历史事实。'),past=ref<string[]>([]),addKind=ref('PROCESS'),addName=ref(''),addProduct=ref(''),addProcess=ref(''),edgeFrom=ref(''),edgeTo=ref('')
const {fitView,zoomIn,zoomOut}=useVueFlow({id:'local-production-editor'})
const graphNodes=shallowRef<Node[]>([]),graphEdges=shallowRef<Edge[]>([])
const previewVersion=ref<Revision>();
const current=computed(()=>def.value.nodes.find(n=>n.id===selected.value)),processes=computed(()=>def.value.nodes.filter(n=>n.kind==='PROCESS')),cost=computed(()=>props.source.costs.find(c=>String(c.projectId)===String(props.project.id))),taskReports=computed(()=>rs('output').filter(r=>String(r.projectId)===String(props.project.id)))
const clone=<T,>(x:T):T=>JSON.parse(JSON.stringify(x))
const label=(c:string)=>String(rs('product').find(p=>p.productCode===c)?.productName||c)
async function api<T>(url:string,body?:unknown):Promise<T>{const r=await fetch(url,{method:body?'POST':'GET',headers:body?{'content-type':'application/json','x-prototype-action':'explicit'}:{},body:body?JSON.stringify(body):undefined});const b=await r.json();if(!r.ok||!b.success)throw Error(b.message);return b.data}
function sync(){graphNodes.value=def.value.nodes.map(n=>({id:n.id,type:'default',position:{...n.position},data:{cell:n}}));graphEdges.value=def.value.edges.map(e=>({...e}));}
function checkpoint(){past.value.push(JSON.stringify(def.value));if(past.value.length>30)past.value.shift();dirty.value=true;notice.value=''}
function undo(){const x=past.value.pop();if(x){def.value=JSON.parse(x);dirty.value=true;sync()}}
async function read(){saved.value=await api<Stored>('/api/local-workflow?productCode='+encodeURIComponent(code));if(saved.value.draft){def.value=clone(saved.value.draft.definition);dirty.value=false;sync()}}
// R21：原生 confirm() 换成共享确认弹层（只问放弃与否，原因可选）；返回 null 表示取消
const discard=async(title:string,message:string,okLabel='放弃改动')=>(await confirmReason({title,message,required:false,okLabel,danger:true}))!==null
async function importReference(){if(def.value.nodes.length&&!await discard('用来源参考替换草稿','用来源参考替换当前草稿？已发布版本保持不变。','替换草稿'))return;checkpoint();const product=rs('product').find(p=>p.productCode===code),route=rs('routing').find(r=>r.processRoutingCode===product?.prcessRoutingCode),steps=Array.isArray(route?.processRoutingSteps)?route!.processRoutingSteps as Row[]:[];def.value={nodes:steps.map((s,i)=>({id:crypto.randomUUID(),kind:'PROCESS',name:String(s.name),productCode:'',unit:'',inputUnit:'',outputUnit:'',reportingRequired:true,position:{x:350+i*600,y:100}})),edges:[],bom:[]};for(const b of rs('bom').filter(b=>b.lastProductCode===code)){const matching=steps.map((s,i)=>({s,i})).filter(x=>x.s.code===b.feedProcessCode);def.value.bom.push({id:crypto.randomUUID(),sourceId:String(b.id),materialCode:String(b.nextProductCode),nodeId:matching.length===1?def.value.nodes[matching[0].i].id:'',quantity:Number(b.unitQty),base:Number(b.parentBaseQty),unit:'',baseUnit:''})}sync();notice.value='已复制当前参考为本地草稿；单位、投入产出和缺失绑定需人工确认，没有自动补连线。';nextTick(()=>fitView({padding:.15}))}
function add(){error.value='';const p=rs('product').find(p=>p.productCode===addProduct.value),process=rs('process').find(p=>String(p.id)===addProcess.value),name=addKind.value==='PROCESS'?(addName.value.trim()||String(process?.name||'')):String(p?.productName||'');if(!name){error.value='请选择产品或填写工序名称';return}checkpoint();const n:Cell={id:crypto.randomUUID(),kind:addKind.value,name,productCode:p?String(p.productCode):'',unit:p?String(p.unit||''):'',inputUnit:'',outputUnit:'',reportingRequired:true,position:{x:60,y:80+def.value.nodes.length*430}};def.value.nodes.push(n);selected.value=n.id;sync();addName.value=''}
function connect(c:Connection){if(!c.source||!c.target)return;const a=def.value.nodes.find(n=>n.id===c.source),b=def.value.nodes.find(n=>n.id===c.target);if(!a||!b||a.id===b.id||(a.kind==='PROCESS')===(b.kind==='PROCESS')||a.kind==='FINISHED_GOOD'||b.kind==='RAW_MATERIAL'){error.value='仅允许物料→工序，或工序→半成品/成品';return}if(def.value.edges.some(e=>e.source===a.id&&e.target===b.id))return;const reaches=(id:string,seen=new Set<string>()):boolean=>{if(id===a.id)return true;if(seen.has(id))return false;seen.add(id);return def.value.edges.filter(e=>e.source===id).some(e=>reaches(e.target,seen))};if(reaches(b.id)){error.value='不能创建循环连线';return}checkpoint();def.value.edges.push({id:crypto.randomUUID(),source:a.id,target:b.id});sync()}
function remove(){if(!current.value)return;checkpoint();const id=current.value.id;def.value.nodes=def.value.nodes.filter(n=>n.id!==id);def.value.edges=def.value.edges.filter(e=>e.source!==id&&e.target!==id);def.value.bom.forEach(b=>{if(b.nodeId===id)b.nodeId=''});selected.value='';sync()}
function remember(){past.value.push(JSON.stringify(def.value));if(past.value.length>30)past.value.shift()}function changed(){dirty.value=true;sync()}
function addBom(){checkpoint();def.value.bom.push({id:crypto.randomUUID(),materialCode:'',nodeId:current.value?.kind==='PROCESS'?current.value.id:'',quantity:1,base:1,unit:'',baseUnit:''})}
function removeBom(id:string){checkpoint();def.value.bom=def.value.bom.filter(b=>b.id!==id);sync()}
async function persist(operation='save'){busy.value=true;error.value='';try{saved.value=await api<Stored>('/api/local-workflow',{factoryId:'LIUSHANMEN',revision:props.source.revision,productCode:code,expectedVersion:saved.value.version,operation,definition:def.value});dirty.value=false;preview.value=false;aiText.value='';notice.value=operation==='save'?'工艺草稿已保存；树、画布和用料明细为同一份定义。':`本地生产版本 v${saved.value.activeProductionVersion} 已发布；历史报工和成本未重新绑定。`}catch(e){preview.value=false;error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
async function analyze(){busy.value=true;error.value='';try{if(dirty.value)throw Error('请先保存草稿，以已保存依据解读');const result=await api<{answer:string;id:string}>('/api/analyze',{factoryId:'LIUSHANMEN',revision:props.source.revision,kind:'project',id:String(props.project.id),question:aiQuestion.value,localWorkflowProductCode:code});aiText.value=result.answer;aiOpen.value=true}catch(e){error.value=e instanceof Error?e.message:'解读失败'}finally{busy.value=false}}
async function restoreVersion(){if(!previewVersion.value)return;if(dirty.value&&!await discard('载入历史版本','放弃未保存改动并载入所选版本？','放弃并载入'))return;checkpoint();def.value=clone(previewVersion.value.definition);sync();notice.value='已从历史版本建立待保存草稿，原发布版本不变。'}async function close(){if(!dirty.value||await discard('关闭工艺编辑','工艺尚未保存，放弃本次改动？'))emit('close')}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
function autoLayout(){checkpoint();const ranks=new Map<string,number>();const rank=(id:string,seen=new Set<string>()):number=>{if(ranks.has(id))return ranks.get(id)!;if(seen.has(id))return 0;seen.add(id);const upstream=def.value.edges.filter(e=>e.target===id);const value=upstream.length?Math.max(...upstream.map(e=>rank(e.source,new Set(seen))))+1:0;ranks.set(id,value);return value};const counts=new Map<number,number>();def.value.nodes.forEach(n=>{const r=rank(n.id),row=counts.get(r)||0;counts.set(r,row+1);n.position={x:60+r*540,y:80+row*430}});sync();nextTick(()=>fitView({padding:.15}))}
onMounted(async()=>{try{await read();const history=await api<{workspace:{analyses:{answer:string;localWorkflowHash?:string;localWorkflowVersion?:number}[]}}>('/api/workspace');const latest=[...history.workspace.analyses].reverse().find(a=>saved.value.draft&&a.localWorkflowHash===saved.value.draft.hash&&a.localWorkflowVersion===saved.value.version);if(latest)aiText.value=latest.answer;nextTick(()=>fitView({padding:.15}))}catch(e){error.value=String(e)}window.addEventListener('beforeunload',beforeUnload)})
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
</script>
<template><div class="local-editor"><header class="wf-top"><div><small>六膳门 · 本地工艺配置</small><h2>{{project.productName}} <span>草稿 · {{dirty?'有未保存改动':saved.draft?'已保存':'尚未保存'}} · 已发布 v{{saved.activeProductionVersion||'—'}}</span></h2></div><button @click="close">返回工单执行</button></header>
<div class="wf-controls"><button @click="importReference" :disabled="busy">复制来源参考</button><button @click="undo" :disabled="!past.length">撤销</button><button @click="autoLayout">自动布局</button><button @click="fitView({padding:.15})">适应画布</button><button @click="zoomOut()">−</button><button @click="zoomIn()">＋</button><button class="primary" @click="persist()" :disabled="busy">保存工艺草稿</button><button @click="preview=true" :disabled="busy||dirty||!saved.draft">发布生产版本</button><button @click="aiOpen=true">检查配置</button></div>
<div class="wf-boundary">人工配置仅用于六膳门本地演示，原始黑湖数据不变。当前参考不等于历史工单版本；发布不会重算或改写历史报工、实耗与成本。</div><p v-if="error" role="alert" class="wf-error">{{error}}</p><p v-if="notice" role="status" class="wf-success">{{notice}}</p>
<div class="wf-body"><aside class="wf-tree"><strong>工艺目录</strong><button v-for="n in def.nodes" :key="n.id" @click="selected=n.id;tab='configure'">{{n.kind==='PROCESS'?'序':n.kind==='FINISHED_GOOD'?'成':n.kind==='SEMI_FINISHED'?'半':'原'}} · {{n.name}}<small>{{def.bom.filter(b=>b.nodeId===n.id).length}} 条用料</small></button><button @click="selected='';tab='bom'">用料明细 {{def.bom.length}}</button><small>未指定工序 {{def.bom.filter(b=>!b.nodeId).length}}</small><hr><label>新增类型<select aria-label="新增节点类型" v-model="addKind"><option value="PROCESS">工序 Cell</option><option value="RAW_MATERIAL">原料 Cell</option><option value="SEMI_FINISHED">半成品 Cell</option><option value="FINISHED_GOOD">成品 Cell</option></select></label><template v-if="addKind==='PROCESS'"><select aria-label="选择标准工序" v-model="addProcess"><option value="">选择现有工序</option><option v-for="p in rs('process')" :key="String(p.id)" :value="String(p.id)">{{p.name}}</option></select><input aria-label="新增工序名称" v-model="addName" placeholder="或输入本地新工序"></template><select v-else aria-label="选择节点产品" v-model="addProduct"><option value="">选择来源产品</option><option v-for="p in rs('product')" :key="String(p.id)" :value="String(p.productCode)">{{p.productName}} · {{p.productCode}}</option></select><button @click="add">＋ 添加节点</button><hr><strong>连接物料与工序</strong><select aria-label="连线起点" v-model="edgeFrom"><option value="">选择起点</option><option v-for="n in def.nodes" :value="n.id" :key="n.id">{{n.name}}</option></select><select aria-label="连线终点" v-model="edgeTo"><option value="">选择终点</option><option v-for="n in def.nodes" :value="n.id" :key="n.id">{{n.name}}</option></select><button @click="connect({source:edgeFrom,target:edgeTo,sourceHandle:null,targetHandle:null})">连接</button><details><summary>已有连线 {{def.edges.length}}</summary><div v-for="e in def.edges" :key="e.id">{{def.nodes.find(n=>n.id===e.source)?.name}} → {{def.nodes.find(n=>n.id===e.target)?.name}} <button @click="checkpoint();def.edges=def.edges.filter(x=>x.id!==e.id);sync()">移除</button></div></details></aside>
<div class="wf-flow"><VueFlow fit-view-on-init @nodes-initialized="fitView({padding:.15})" id="local-production-editor" v-model:nodes="graphNodes" v-model:edges="graphEdges" :min-zoom=".15" :max-zoom="1.8" :delete-key-code="null" @connect="connect" @node-click="({node})=>{selected=node.id;tab='configure'}" @node-drag-start="checkpoint" @node-drag-stop="({node})=>{const c=def.nodes.find(n=>n.id===node.id);if(c)c.position={...node.position}}"><template #node-default="{data}"><Handle v-if="data.cell.kind!=='RAW_MATERIAL'" type="target" :position="Position.Left"/><Handle v-if="data.cell.kind!=='FINISHED_GOOD'" type="source" :position="Position.Right"/><div :class="['native-cell',data.cell.kind==='PROCESS'?'process-cell':'material-cell']"><div class="cell-heading"><b>{{data.cell.kind==='PROCESS'?'序':data.cell.kind==='FINISHED_GOOD'?'成':data.cell.kind==='SEMI_FINISHED'?'半':'原'}}</b><div><small>{{data.cell.kind==='PROCESS'?'工序 Cell':data.cell.kind==='FINISHED_GOOD'?'成品 Cell':data.cell.kind==='SEMI_FINISHED'?'半成品 Cell':'原料 Cell'}}</small><strong>{{data.cell.name}}</strong></div><span>本地配置</span></div><template v-if="data.cell.kind==='PROCESS'"><div class="cell-badge">可报工接口 · {{def.edges.filter(e=>e.target===data.cell.id).length}} 个投入 · {{def.edges.filter(e=>e.source===data.cell.id).length}} 个产出</div><div class="port-section"><strong>投入物料</strong><p v-for="e in def.edges.filter(e=>e.target===data.cell.id)" :key="e.id">{{def.nodes.find(n=>n.id===e.source)?.name}} <em>{{data.cell.inputUnit||'单位待确认'}}</em></p><p v-if="!def.edges.some(e=>e.target===data.cell.id)">待连接来源 Cell</p></div><div class="port-section"><strong>产出物料</strong><p v-for="e in def.edges.filter(e=>e.source===data.cell.id)" :key="e.id">{{def.nodes.find(n=>n.id===e.target)?.name}} <em>{{data.cell.outputUnit||'单位待确认'}}</em></p><p v-if="!def.edges.some(e=>e.source===data.cell.id)">待连接产出 Cell</p></div><div class="cell-relation">单位关系　{{data.cell.inputUnit||'—'}} → {{data.cell.outputUnit||'—'}} · {{data.cell.reportingRequired?'报工':'不报工'}}</div><div class="fused-strip">辅 · 用料配置 {{def.bom.filter(b=>b.nodeId===data.cell.id).length}} 项<div v-for="b in def.bom.filter(b=>b.nodeId===data.cell.id)" :key="b.id">{{label(b.materialCode)}} · {{b.quantity}} {{b.unit||'单位待确认'}} / {{b.base}} {{b.baseUnit||'单位待确认'}}</div></div></template><template v-else><div class="sku-row">SKU <span>{{data.cell.productCode}}</span></div><div class="sku-row">单位 <span>{{data.cell.unit||'待确认'}}</span></div></template></div></template></VueFlow><div class="wf-flow-help">拖动节点 · 从端口拖线或用目录连接 · 更改为人工本地配置</div></div>
<section class="wf-inspector"><nav><button @click="tab='configure'">配置</button><button @click="tab='bom'">BOM</button><button @click="tab='evidence'">执行依据</button><button @click="tab='versions'">版本</button></nav><template v-if="tab==='configure'"><h3>{{current?.name||'选择节点进行配置'}}</h3><div v-if="current" class="config-fields"><label>名称<input @focus="remember" aria-label="节点名称" v-model="current.name" @change="changed"></label><template v-if="current.kind==='PROCESS'"><label>投入单位<input @focus="remember" aria-label="投入单位" v-model="current.inputUnit" @change="changed"></label><label>产出单位<input @focus="remember" aria-label="产出单位" v-model="current.outputUnit" @change="changed"></label><label><input type="checkbox" v-model="current.reportingRequired" @change="changed">本道是否报工</label></template><label v-else>物料单位<input aria-label="物料单位" v-model="current.unit" @change="changed"></label><button @click="addBom();tab='bom'">配置用料</button><button @click="remove">删除节点</button></div><p>可连接多个投入和产出；删除工序会将其用料保留为待指定。</p></template>
<template v-if="tab==='bom'"><h3>标准用料 · {{def.bom.length}} 项</h3><button @click="addBom">＋ 添加用料</button><article v-for="b in def.bom" :key="b.id" class="bom-item"><small>{{b.sourceId?'来源参考行 '+b.sourceId:'人工新增用料'}}</small><label>物料<select aria-label="用料产品" v-model="b.materialCode" @change="changed"><option value="">选择产品</option><option v-for="p in rs('product')" :key="String(p.id)" :value="String(p.productCode)">{{p.productName}}</option></select></label><label>投料工序<select aria-label="投料工序" v-model="b.nodeId" @change="changed"><option value="">待指定工序</option><option v-for="n in processes" :key="n.id" :value="n.id">{{n.name}}</option></select></label><div class="bom-numbers"><label>标准量<input @focus="remember" aria-label="标准量" type="number" min="0.000001" step="any" v-model.number="b.quantity" @change="changed"></label><label>单位<input aria-label="用料单位" v-model="b.unit" @change="changed"></label><label>产出基数<input aria-label="产出基数" type="number" min="0.000001" step="any" v-model.number="b.base" @change="changed"></label><label>基数单位<input aria-label="基数单位" v-model="b.baseUnit" @change="changed"></label></div><button @click="removeBom(b.id)">移除此用料</button></article><p>标准用料不代表实际领料。单位必须由操作者确认，未自动换算成 g/kg。</p></template>
<template v-if="tab==='evidence'"><h3>来源工单 {{project.projectCode}}</h3><p>新工艺版本不改变这些历史事实。</p><table><tr><th>报工记录</th><th>良品</th></tr><tr v-for="r in taskReports" :key="String(r.id)"><td>{{r.id}}</td><td>{{r.numberofgoodProducts}} {{r.stockUnit}}</td></tr></table><p>工单良品 {{cost?.finishedGood}} {{cost?.unit}}</p><p>材料 {{cost?.materialCost}} · 人工 {{cost?.laborCost}}</p><p>单位直接成本 {{cost?.unitIdentifiedDirectCost}}（币种待确认）</p><details><summary>实际领退料</summary><p v-for="(m,i) in cost?.materialLinesDetail" :key="i">{{m.orderCode}} · {{m.netConsumption}} {{m.unit}} · {{m.recognizedCost}}</p></details></template>
<template v-if="tab==='versions'"><h3>本地生产版本</h3><button v-for="v in saved.published" :key="v.hash+v.version" @click="previewVersion=v">v{{v.productionVersion}} · {{bjTime(v.at)}} · {{v.hash.slice(0,8)}}</button><p>已发布版本不可修改。保存修改产生新草稿；历史工单不自动绑定。</p><p>当前草稿 {{saved.draft?.hash.slice(0,12)||'未保存'}}</p><div v-if="previewVersion"><h4>只读核对 v{{previewVersion.productionVersion}}</h4><p>{{previewVersion.definition.nodes.length}} 个节点 · {{previewVersion.definition.edges.length}} 条连线</p><p v-for="b in previewVersion.definition.bom" :key="b.id">{{label(b.materialCode)}} · {{b.quantity}} {{b.unit}} / {{b.base}} {{b.baseUnit}}</p><button @click="restoreVersion">从此版本建立草稿</button></div></template></section></div>
<UModal v-model:open="preview" title="发布本地生产版本"><template #body><p>产品 {{project.productName}} · 工序 {{processes.length}} 道 · 用料 {{def.bom.length}} 项</p><p>将发布 v{{saved.published.length+1}}，只保存到六膳门独立原型。不会回写黑湖或修改历史工单。</p><p>草稿哈希 {{saved.draft?.hash}}</p><button @click="preview=false">返回修改</button><button @click="persist('publish')" :disabled="busy">确认发布</button></template></UModal>
<section v-if="aiOpen" class="wf-ai" role="dialog" aria-label="配置检查"><header><strong>检查配置 · 已保存本地草稿</strong><button @click="aiOpen=false">×</button></header><p>当前产品 {{code}} · {{saved.draft?.hash.slice(0,12)||'未保存'}}</p><textarea aria-label="配置解读问题" v-model="aiQuestion"/><button @click="analyze" :disabled="busy">开始检查</button><div class="wf-answer"><template v-for="(line,i) in analysisLines(aiText)" :key="i"><h4 v-if="line.heading">{{line.text}}</h4><p v-else>{{line.text}}</p></template><p v-if="!aiText">先保存工艺草稿，再检查并核对来源。</p></div><button @click="tab='bom';aiOpen=false">定位用料配置</button><button @click="persist();aiOpen=false" :disabled="busy">保存当前草稿</button></section></div></template>
<style scoped>
